import type { ForkSessionOptions, ForkSessionResult } from '../types/session.js';
/**
 * Fork a session into a new independent session with fresh UUIDs.
 *
 * Creates a copy of the source session's JSONL file with all UUIDs
 * remapped to new values. This allows the forked session to diverge
 * from the original without sharing message identifiers.
 *
 * Optional parameters:
 * - `upToMessageId` — Only copy messages up to and including this message
 * - `title` — Set a custom title on the forked session
 * - `dir` — Restrict the session search to this working directory
 *
 * @param sessionId - The source session UUID to fork from
 * @param options - Fork options
 * @returns The new session's UUID
 * @throws Error if the source session is not found
 *
 * @example
 * ```ts
 * // Fork the entire session
 * const { sessionId: newId } = await forkSession('abc-123');
 *
 * // Fork up to a specific message with a custom title
 * const { sessionId } = await forkSession('abc-123', {
 *   upToMessageId: 'msg-456',
 *   title: 'Exploration branch',
 * });
 * ```
 */
export declare function forkSession(sessionId: string, options?: ForkSessionOptions): Promise<ForkSessionResult>;